  trophy:'M8 3h8v6a4 4 0 0 1-8 0z M8 5H4v3a4 4 0 0 0 4 4 M16 5h4v3a4 4 0 0 1-4 4 M12 13v5 M8 21h8 M9 18h6',
  medal:'M8 3l4 7 4-7 M5 3h4 M15 3h4 M18 15a6 6 0 1 1-12 0 6 6 0 0 1 12 0 M12 12v6 M9 15h6',
