  upload:'M12 16V3 M7 8l5-5 5 5 M3 15v5a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-5',
  download:'M12 3v13 M7 11l5 5 5-5 M3 17v4h18v-4', search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
  plus:'M12 5v14 M5 12h14', arrow:'M5 12h14 M14 7l5 5-5 5', chevron:'M9 5l7 7-7 7', back:'M19 12H5 M10 7l-5 5 5 5',
