  const fields=athlete
    ? `<div class="field full"><strong>${html(record.full_name)}</strong><span>${text(record.official_code)}</span></div><div class="field full">${checkbox('public_profile_allowed','Cho phép khách tìm và xem tên, mã chính thức của hồ sơ này',Boolean(record.public_profile_allowed))}</div><div class="field full"><p class="inline-note">Ngày sinh, năm sinh, cơ sở hiện tại và ghi chú nội bộ không xuất hiện trên trang tra cứu. Thành tích chỉ xuất hiện khi được cấp quyền công bố riêng.</p></div>`
    : `<div class="field full"><strong>${html(record.event_name)}</strong><span>${html(record.tournament_name||'')}</span></div><div class="field full">${checkbox('public_search_allowed','Công bố kết quả đã xác minh trên trang tra cứu dành cho khách',Boolean(record.public_search_allowed))}</div><div class="field full">${checkbox('public_evidence_allowed','Công bố cả đường dẫn URL minh chứng cho khách',Boolean(record.public_evidence_allowed))}</div><div class="field full"><p class="inline-note">Kết quả cần được xác minh và bật quyền hiển thị. Tên thành viên chỉ xuất hiện khi hồ sơ của thành viên đó đã được công bố. URL minh chứng cần được kiểm tra phù hợp cho khách; tệp tải lên có quyền công bố riêng trong chi tiết kết quả.</p></div>`;
  openForm(athlete?'Công bố hồ sơ cho khách':'Công bố thành tích cho khách',fields,async f=>api('/api/publication/'+entity+'/'+encodeURIComponent(id),{method:'PATCH',body:{version:record.version,...formObject(f,athlete?['public_profile_allowed']:['public_search_allowed','public_evidence_allowed'])}}),{notice:notice('Đây là quyền xem không cần đăng nhập. Chỉ bật sau khi đã kiểm tra nội dung và quyền công bố. Tắt quyền để gỡ khỏi trang tra cứu.','info'),submitLabel:'Lưu quyền công bố',success:'Đã cập nhật trang tra cứu công khai.'});
