  openForm('Đối chiếu thông tin nguồn',fields,async f=>api('/api/queue/'+encodeURIComponent(id),{method:'PATCH',body:{version:q.version,...formObject(f,[],['reported_quantity'])}}),{wide:true,submitLabel:'Lưu xử lý',notice:notice('Không chuyển số huy chương tổng hợp thành kết quả cá nhân. Chỉ liên kết khi đã nhận diện đủ người nhận và đối chiếu minh chứng.','info')});
