document.addEventListener('click',async e=>{
  const a=e.target.closest('[data-action]');if(!a||a.disabled)return;const action=a.dataset.action;const id=a.dataset.id;
  try{
    switch(action){
      case 'reload':location.reload();break;
      case 'refresh':await navigate();break;
      case 'drawer':$('.shell')?.classList.toggle('drawer-open');break;
      case 'modal-close':closeModal();break;
      case 'logout':await api('/api/logout',{method:'POST',body:{}});state.session=null;state.preview=null;location.hash='';await bootstrap();break;
      case 'page':state.page=Number(a.dataset.page);await navigate();break;
      case 'export':window.location.href='/api/export';break;
      case 'new-athlete':await editAthlete();break;
      case 'edit-athlete':await editAthlete(id);break;
      case 'publish-athlete':await editPublication('athletes',id);break;
      case 'publish-achievement':await editPublication('achievements',id);break;
      case 'athlete-view':location.hash='#athletes/'+id;break;
      case 'portal-preview':state.portalId=id;location.hash='#portal';break;
      case 'new-tournament':await editTournament();break;
      case 'edit-tournament':await editTournament(id);break;
      case 'new-achievement':await editAchievement();break;
      case 'tournament-achievement':case 'queue-create':await editAchievement(null,id);break;
      case 'edit-achievement':await editAchievement(id);break;
      case 'achievement-view':await viewAchievement(id);break;
      case 'verify-achievement':await verifyAchievement(id);break;
      case 'return-achievement':await returnAchievement(id);break;
      case 'queue-view':await viewQueue(id);break;
      case 'source':await showSource(id);break;
      case 'new-branch':await editBranch();break;
      case 'edit-branch':await editBranch(id);break;
      case 'new-user':await editUser();break;
      case 'edit-user':await editUser(id);break;
      case 'archive':await archiveEntity(id);break;
      case 'archive-confirm':{const x=state.editing;await api('/api/'+x.entity+'/'+encodeURIComponent(id),{method:'DELETE',body:{version:x.record.version}});closeModal();state.allAthletes=[];state.allTournaments=[];await loadCommon();location.hash='#'+x.entity;await navigate();toast('Đã lưu trữ bản ghi và giữ lịch sử.');break;}
      case 'warnings-all':$('#validation-warnings').innerHTML=validationList(state.preview?.warnings||[],false,true);break;
      case 'import-cancel':if(state.preview?.token)await api('/api/import/cancel',{method:'POST',body:{token:state.preview.token}});state.preview=null;await navigate();toast('Đã hủy thao tác nhập.');break;
      case 'import-commit':{if(!state.preview?.token)throw new Error('Phiên xem trước đã hết. Vui lòng chọn lại tệp.');if(state.preview.errors?.length||state.preview.existing_file)throw new Error('Tệp không thể nhập. Vui lòng kiểm tra lỗi hoặc tệp đã nhập.');a.disabled=true;const result=await api('/api/import/commit',{method:'POST',body:{token:state.preview.token}});state.preview=null;state.allAthletes=[];state.allTournaments=[];await loadCommon();await navigate();toast(result.message||'Đã nhập dữ liệu. Các kết quả đang chờ xác minh.');break;}
    }
  }catch(err){toast(err.message,true);a.disabled=false;}
});
window.addEventListener('hashchange',navigate);
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
bootstrap();
